\begin{aligned}
Map(f,a,b):={}&B(f)\wedge B(a)\wedge B(b)\\
&\wedge\forall p(p\in f\to\exists x\exists y(x\in a\wedge y\in b\wedge OP(p,x,y)))\\
&\wedge\forall x(x\in a\to\exists!y(y\in b\wedge Val(f,x,y))),
\end{aligned}

\begin{aligned}
OrdIso(f,a,b):={}&Bij(f,a,b)\wedge\forall x\forall x'\forall y\forall y'\bigl(
(x\in a\wedge x'\in a\wedge Val(f,x,y)\wedge Val(f,x',y'))\\
&\hspace{42mm}\to(x\in x'\leftrightarrow y\in y')\bigr),
\end{aligned}

\begin{aligned}
Wis(h):=B(h)\wedge\forall a\bigl(a\in h\to[B(a)\wedge
\forall x(x\in a\leftrightarrow\exists r(r\in a\wedge r\in h\wedge Found(x,r)))]\bigr),
\end{aligned}

\begin{aligned}
Ord(a):={}&Heb(a)\wedge Trans(a)\wedge\forall x(x\in a\to Trans(x))\\
&\wedge\forall x\forall y((x\in a\wedge y\in a)\to(x\in y\vee x\doteq y\vee y\in x))\\
&\wedge\forall c((Sub(c,a)\wedge NE(c))\to
\exists m(m\in c\wedge\forall y(y\in c\to\neg(y\in m)))).
\end{aligned}

\begin{aligned}
Iter(n,a,A):={}&Pos(n)\wedge Seq(A,n)\wedge Val(A,\mathbf0,a)\\
&\wedge\forall i\forall j\forall u\forall v\bigl(
(i\in n\wedge j\in n\wedge Succ(i,j)\wedge Val(A,i,u)\wedge Val(A,j,v))
\to Union(u,v)\bigr).
\end{aligned}

\begin{aligned}
Lift(f,g,a,b):=\forall x\forall z\bigl((x\in a\wedge z\in b\wedge Val(f,x,z))\to
\forall y(y\in z\leftrightarrow\exists u(u\in x\wedge Val(g,u,y)))\bigr).
\end{aligned}

\begin{aligned}
Ax_{Card1}:=\{cl((&Pos(m)\wedge Pos(n))\to\\
&((\exists c(T(m,a,c)\wedge T(n,b,c)))\leftrightarrow(m\doteq n\wedge EqN(m,a,b)))):
m,n,a,b\in\mathsf{Term}_{C}\},
\end{aligned}

\begin{aligned}
Ax_{Card2}:=\{cl((&Pos(m)\wedge B(b)\wedge T(m,a,c)\wedge T(\mathbf0,b,d))\to c\ne d):
m,a,b,c,d\in\mathsf{Term}_{C}\},
\end{aligned}

\begin{aligned}
Ax_{Card3}:=\{cl((&Pos(m)\wedge Pos(n)\wedge T(m,a,c)\wedge T(n,b,d)\wedge T(\mathbf0,d,e))
\to c\ne e):m,n,a,b,c,d,e\in\mathsf{Term}_{C}\}.
\end{aligned}

\begin{aligned}
Ax_{CUS}:={}&Ax_{Log}\cup Ax_{In}\cup Ax_{TapNB}\cup Ax_{TapFun}\cup Ax_{Ext}
\cup Ax_0\cup Ax_{Wands}\cup Ax_{Sep}\\
&\cup Ax_{Strat}\cup Ax_{Height}\cup Ax_{Making}\cup Ax_{Comp1}\cup Ax_{Comp2}
\cup Ax_{Card1}\cup Ax_{Card2}\cup Ax_{Card3}.
\end{aligned}

\begin{aligned}
x\,\varepsilon\,a:={}&(B(a)\wedge x\in a)\\
&\vee\exists b(B(b)\wedge T(\mathbf0,b,a)\wedge\neg(x\in b))\\
&\vee\exists n\exists b(Pos(n)\wedge B(b)\wedge T(n,b,a)\wedge EqN(n,x,b))\\
&\vee\exists n\exists b\exists c(Pos(n)\wedge B(b)\wedge T(n,b,c)\wedge T(\mathbf0,c,a)\wedge\neg EqN(n,x,b)).
\end{aligned}
